import bisect
from typing import List

class Solution:
    def findRightInterval(self, intervals: List[List[int]]) -> List[int]:
        starts = sorted([(iv[0], i) for i, iv in enumerate(intervals)])
        start_vals = [s[0] for s in starts]
        res = []

        for start, end in intervals:
            idx = bisect.bisect_left(start_vals, end)
            if idx < len(starts):
                res.append(starts[idx][1])
            else:
                res.append(-1)

        return res

class Solution {
public:
    vector<int> findRightInterval(vector<vector<int>>& intervals) {
        int n = intervals.size();
        vector<pair<int, int>> starts(n);
        for (int i = 0; i < n; i++) {
            starts[i] = {intervals[i][0], i};
        }
        sort(starts.begin(), starts.end());

        vector<int> res(n);
        for (int i = 0; i < n; i++) {
            int target = intervals[i][1];
            auto it = lower_bound(starts.begin(), starts.end(), make_pair(target, -1));
            if (it != starts.end()) {
                res[i] = it->second;
            } else {
                res[i] = -1;
            }
        }
        return res;
    }
};

class Solution {
    public int[] findRightInterval(int[][] intervals) {
        int n = intervals.length;
        int[][] starts = new int[n][2];
        for (int i = 0; i < n; i++) {
            starts[i][0] = intervals[i][0];
            starts[i][1] = i;
        }
        Arrays.sort(starts, (a, b) -> Integer.compare(a[0], b[0]));

        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            int target = intervals[i][1];
            int low = 0, high = n - 1, best = -1;
            while (low <= high) {
                int mid = (low + high) >>> 1;
                if (starts[mid][0] >= target) {
                    best = starts[mid][1];
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }
            res[i] = best;
        }
        return res;
    }
}

var findRightInterval = function(intervals) {
    const n = intervals.length;
    const starts = intervals.map((iv, i) => [iv[0], i]);
    starts.sort((a, b) => a[0] - b[0]);

    const res = new Array(n);
    for (let i = 0; i < n; i++) {
        const target = intervals[i][1];
        let low = 0, high = n - 1, best = -1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (starts[mid][0] >= target) {
                best = starts[mid][1];
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        res[i] = best;
    }
